    let result: Value = serde_json::from_str(json).expect("json parse error");
    let mut len = 0;
    if let Some(vec) = result.as_array() {
        for item in vec {
            if let Some(form_value_list) = item.get("formValueList") {
                if let Some(form_value_list) = form_value_list.as_array() {
                    form_value_list.iter().find_map(|value| {
                        if let Some(field_name) = value.get("fieldName") {
                            if field_name == "standard" {
                                let standard =
                                    value.get("value").map(|value: &Value| value.as_str());
                                if let Some(standard) = standard {
                                    if let Some(standard) = standard {
                                        if len < standard.chars().count() {
                                            len = standard.chars().count();
                                            println!("standard (len={}): {:?}", len, standard);
                                        }
                                    }
                                }
                                return Some(standard);
                            }
                        }
                        None
                    });
                }
            }
        }
    }
